import java.io.*;
import java.net.*;
import java.util.*;
import com.sun.net.httpserver.*;
import java.sql.*;
import java.util.regex.*;

public class AuditLogService {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Allowlist for sort columns - looks secure but sortDir is not validated
    private static final Set<String> VALID_COLUMNS = Set.of(
        "timestamp", "user_id", "action", "resource", "ip_address");

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/audit/search", AuditLogService::handleSearch);
        server.createContext("/healthz", ex -> {
            ex.sendResponseHeaders(200, 2);
            ex.getResponseBody().write("OK".getBytes());
            ex.getResponseBody().close();
        });
        server.start();
    }

    static void handleSearch(HttpExchange exchange) throws IOException {
        if (!"GET".equals(exchange.getRequestMethod())) {
            exchange.sendResponseHeaders(405, 0); exchange.getResponseBody().close(); return;
        }
        Map<String, String> params = parseQuery(exchange.getRequestURI().getQuery());

        String userId = params.getOrDefault("user_id", "");
        String action = params.getOrDefault("action", "");
        String sortCol = params.getOrDefault("sort", "timestamp");
        String sortDir = params.getOrDefault("dir", "DESC");
        String limit = params.getOrDefault("limit", "50");

        // Validate sort column against allowlist
        if (!VALID_COLUMNS.contains(sortCol)) {
            sortCol = "timestamp";
        }
        // Validate limit is numeric
        if (!limit.matches("^\\d{1,3}$")) {
            limit = "50";
        }

        // Developer note: sortDir is constrained by the ORDER BY position,
        // only ASC/DESC are syntactically valid there... right?
        // Actually this is injectable - sortDir is not validated

        StringBuilder sql = new StringBuilder();
        sql.append("SELECT id, timestamp, user_id, action, resource, ip_address ");
        sql.append("FROM audit_log WHERE 1=1 ");

        if (!userId.isEmpty()) {
            sql.append("AND user_id = ? ");
        }
        if (!action.isEmpty()) {
            sql.append("AND action = ? ");
        }
        sql.append("ORDER BY ").append(sortCol).append(" ").append(sortDir);
        sql.append(" LIMIT ").append(limit);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql.toString())) {

            int paramIdx = 1;
            if (!userId.isEmpty()) stmt.setString(paramIdx++, userId);
            if (!action.isEmpty()) stmt.setString(paramIdx++, action);

            ResultSet rs = stmt.executeQuery();
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append(String.format(
                    "  {\"id\":%d,\"timestamp\":\"%s\",\"user_id\":\"%s\",\"action\":\"%s\",\"resource\":\"%s\",\"ip\":\"%s\"}",
                    rs.getInt(1), rs.getString(2), rs.getString(3),
                    rs.getString(4), rs.getString(5), rs.getString(6)));
                first = false;
            }
            json.append("\n]");
            byte[] resp = json.toString().getBytes();
            exchange.getResponseHeaders().set("Content-Type", "application/json");
            exchange.sendResponseHeaders(200, resp.length);
            exchange.getResponseBody().write(resp);
        } catch (SQLException e) {
            byte[] err = ("DB error: " + e.getMessage()).getBytes();
            exchange.sendResponseHeaders(500, err.length);
            exchange.getResponseBody().write(err);
        }
        exchange.getResponseBody().close();
    }

    static Map<String, String> parseQuery(String query) {
        Map<String, String> map = new HashMap<>();
        if (query == null) return map;
        for (String pair : query.split("&")) {
            String[] kv = pair.split("=", 2);
            if (kv.length == 2) {
                map.put(URLDecoder.decode(kv[0], java.nio.charset.StandardCharsets.UTF_8),
                        URLDecoder.decode(kv[1], java.nio.charset.StandardCharsets.UTF_8));
            }
        }
        return map;
    }
}
